"use client";

import React, { useState } from "react";
import Link from "next/link";
import { Wallet, Users, Globe, Sparkles, Zap, ArrowRight, ShieldCheck, Smartphone, RefreshCw, Check } from "lucide-react";

export default function LandingPage() {
  // Estado para el simulador interactivo en vivo de la landing
  const [simName, setSimName] = useState("Despensa del súper");
  const [simAmount, setSimAmount] = useState(7000);
  const [simCurrency, setSimCurrency] = useState("ARS");
  const [simCat, setSimCat] = useState("súper");
  const [simWho, setSimWho] = useState("yo");
  const [simList, setSimList] = useState([
    { id: "1", name: "Despensa del súper", amount: 7000, currency: "ARS", who: "yo", date: "Justo ahora" },
    { id: "2", name: "Cena de Aniversario", amount: 85, currency: "USD", who: "yo", date: "Hace 5 minutos" },
    { id: "3", name: "Factura de Internet", amount: 45, currency: "USD", who: "pareja", date: "Ayer" }
  ]);

  const addSimExpense = (e: React.FormEvent) => {
    e.preventDefault();
    if (!simName || !simAmount) return;
    const newItem = {
      id: crypto.randomUUID(),
      name: simName,
      amount: Number(simAmount),
      currency: simCurrency,
      who: simWho,
      date: "Justo ahora"
    };
    setSimList([newItem, ...simList]);
  };

  const totalSim = simList.reduce((acc, item) => acc + (item.currency === "ARS" ? item.amount / 1000 : item.amount), 0);

  return (
    <div className="min-h-screen selection:bg-primary selection:text-primary-foreground">
      {/* Navbar superior */}
      <header className="mx-auto flex max-w-7xl items-center justify-between px-6 py-6">
        <div className="flex items-center gap-3">
          <div className="grid h-11 w-11 place-items-center rounded-2xl border border-primary/40 bg-primary/15 shadow-[0_0_24px_-6px_var(--primary)]">
            <Wallet className="h-5 w-5 text-primary" />
          </div>
          <span className="text-xl font-bold tracking-tight">Mis Gastos</span>
        </div>

        <nav className="hidden md:flex items-center gap-8 text-sm font-medium text-muted-foreground">
          <a href="#modo-pareja" className="transition hover:text-foreground">Modo Pareja</a>
          <a href="#multi-moneda" className="transition hover:text-foreground">Multi-Moneda</a>
          <a href="#simulador" className="transition hover:text-foreground">Simulador en Vivo</a>
          <a href="#instalar" className="transition hover:text-foreground">Instalar App</a>
        </nav>

        <div className="flex items-center gap-4">
          <Link href="/login" className="text-sm font-semibold transition hover:text-primary">
            Iniciar sesión
          </Link>
          <Link
            href="/register"
            className="flex items-center gap-2 rounded-xl bg-primary px-5 py-2.5 text-sm font-semibold text-primary-foreground shadow-lg shadow-primary/30 transition hover:scale-105"
          >
            Registrarse gratis <ArrowRight className="h-4 w-4" />
          </Link>
        </div>
      </header>

      {/* Hero Section */}
      <section className="mx-auto max-w-5xl px-6 pt-12 pb-20 text-center">
        <div className="inline-flex items-center gap-2 rounded-full border border-primary/30 bg-primary/10 px-4 py-1.5 text-xs font-semibold text-primary backdrop-blur-md">
          <Sparkles className="h-3.5 w-3.5" /> Tu gestor financiero inteligente y rápido
        </div>
        <h1 className="mt-6 text-4xl font-extrabold tracking-tight sm:text-6xl lg:text-7xl">
          Toma el control de tus finanzas <span className="text-transparent bg-clip-text bg-gradient-to-r from-primary to-[oklch(0.58_0.26_305)]">solas o en pareja</span>
        </h1>
        <p className="mx-auto mt-6 max-w-2xl text-lg text-muted-foreground">
          Registra tus gastos en segundos, cambia de moneda automáticamente según tu región y lleva cuentas claras sin complicaciones. Instálala en tu celular como una app nativa.
        </p>
        <div className="mt-10 flex flex-wrap justify-center gap-4">
          <Link
            href="/register"
            className="group flex items-center gap-3 rounded-2xl bg-primary px-8 py-4 font-bold text-primary-foreground shadow-[0_10px_40px_-8px_var(--primary)] transition-all hover:scale-105"
          >
            Comenzar ahora <ArrowRight className="h-5 w-5 transition-transform group-hover:translate-x-1" />
          </Link>
          <a
            href="#simulador"
            className="flex items-center gap-2 rounded-2xl border border-border bg-card/60 px-8 py-4 font-semibold backdrop-blur-md transition hover:bg-secondary"
          >
            Probar simulador en vivo ↓
          </a>
        </div>
      </section>

      {/* Características Breves */}
      <div className="mx-auto max-w-4xl px-6 py-8 flex flex-wrap justify-center gap-8 text-sm text-muted-foreground border-y border-border/50">
        <span className="flex items-center gap-2">❤️ División equitativa 50/50</span>
        <span className="flex items-center gap-2">⚡ PWA: Sin descarga de App Store</span>
        <span className="flex items-center gap-2">🔒 Datos 100% privados</span>
      </div>

      {/* Sección Modo Pareja / Cuentas claras */}
      <section id="modo-pareja" className="mx-auto max-w-6xl px-6 py-20 text-center">
        <div className="inline-flex items-center gap-2 rounded-full border border-primary/30 bg-primary/10 px-4 py-1.5 text-xs font-semibold text-primary mb-4">
          Diseñado para tu vida real
        </div>
        <h2 className="text-3xl font-extrabold tracking-tight sm:text-5xl">
          Cuentas claras, <span className="text-transparent bg-clip-text bg-gradient-to-r from-primary to-[oklch(0.58_0.26_305)]">relaciones sanas</span>
        </h2>
        <p className="mx-auto mt-4 max-w-2xl text-muted-foreground">
          Ya sea que compartas alquiler y despensa con tu pareja, o quieras organizar tus ingresos personales, Mis Gastos se adapta a tu dinámica sin fórmulas complicadas.
        </p>
      </section>

      {/* Simulador en Vivo Section */}
      <section id="simulador" className="mx-auto max-w-6xl px-6 py-16">
        <div className="text-center mb-12">
          <div className="inline-flex items-center gap-2 rounded-full border border-primary/30 bg-primary/10 px-4 py-1.5 text-xs font-semibold text-primary mb-3">
            Experiencia Interactiva
          </div>
          <h2 className="text-3xl font-extrabold tracking-tight sm:text-4xl">Pruébalo tú mismo en vivo</h2>
          <p className="mt-2 text-sm text-muted-foreground">Registra un gasto simulado aquí abajo y observa cómo la aplicación recalcula los saldos y cuentas compartidas.</p>
        </div>

        <div className="grid gap-8 lg:grid-cols-2 rounded-3xl border border-border bg-card/40 p-6 sm:p-8 backdrop-blur-xl">
          {/* Formulario simulador */}
          <form onSubmit={addSimExpense} className="space-y-4">
            <h3 className="text-base font-bold text-foreground">Registrar Movimiento</h3>
            <div>
              <label className="text-xs text-muted-foreground font-semibold uppercase">Concepto o Descripción</label>
              <input type="text" value={simName} onChange={(e) => setSimName(e.target.value)}
                className="w-full mt-1 rounded-xl border border-input bg-secondary/40 px-4 py-3 outline-none focus:border-primary text-sm" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs text-muted-foreground font-semibold uppercase">Monto</label>
                <input type="number" value={simAmount} onChange={(e) => setSimAmount(Number(e.target.value))}
                  className="w-full mt-1 rounded-xl border border-input bg-secondary/40 px-4 py-3 outline-none focus:border-primary text-sm font-bold" />
              </div>
              <div>
                <label className="text-xs text-muted-foreground font-semibold uppercase">Moneda</label>
                <select value={simCurrency} onChange={(e) => setSimCurrency(e.target.value)}
                  className="w-full mt-1 rounded-xl border border-input bg-secondary/40 px-4 py-3 outline-none focus:border-primary text-sm font-semibold">
                  <option value="ARS">ARS ($)</option>
                  <option value="USD">USD ($)</option>
                  <option value="EUR">EUR (€)</option>
                </select>
              </div>
            </div>
            <button type="submit" className="w-full rounded-xl bg-primary py-3.5 font-semibold text-primary-foreground shadow-lg shadow-primary/30 transition hover:scale-[1.02]">
              Simular Gasto ⚡
            </button>
          </form>

          {/* Resultado Simulador */}
          <div className="rounded-2xl border border-border bg-background/50 p-6 flex flex-col justify-between">
            <div>
              <div className="flex items-center justify-between mb-4">
                <span className="text-xs font-semibold text-muted-foreground uppercase">Estado en tiempo real</span>
                <span className="flex items-center gap-1.5 text-xs text-primary font-semibold"><RefreshCw className="h-3 w-3 animate-spin" /> Sincronizado</span>
              </div>
              <p className="text-3xl font-extrabold">${totalSim.toFixed(2)}</p>
              <p className="text-xs text-muted-foreground mt-1">{simList.length} movimientos registrados</p>
            </div>

            <div className="mt-6 space-y-3">
              <p className="text-xs font-bold text-muted-foreground uppercase">Historial reciente</p>
              {simList.slice(0, 3).map((item) => (
                <div key={item.id} className="flex items-center justify-between rounded-xl bg-secondary/30 p-3 text-xs">
                  <div>
                    <p className="font-bold">{item.name}</p>
                    <p className="text-[10px] text-muted-foreground">Pagó {item.who === "yo" ? "Tú" : "Pareja"} · {item.date}</p>
                  </div>
                  <span className="font-bold">{item.amount} {item.currency}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Sección Multi-Moneda */}
      <section id="multi-moneda" className="mx-auto max-w-6xl px-6 py-16 text-center">
        <h2 className="text-3xl font-extrabold tracking-tight sm:text-5xl">
          Moneda automática <span className="text-transparent bg-clip-text bg-gradient-to-r from-primary to-[oklch(0.58_0.26_305)]">según tu región</span>
        </h2>
        <p className="mx-auto mt-4 max-w-2xl text-muted-foreground">
          ¿Viajando por el mundo o tu pareja vive en otro país? Mis Gastos detecta tu ubicación y convierte las divisas al instante.
        </p>
      </section>

      {/* Sección Instalar App (PWA) */}
      <section id="instalar" className="mx-auto max-w-6xl px-6 py-16 text-center">
        <h2 className="text-3xl font-extrabold tracking-tight sm:text-4xl">
          Instálala en tu celular <span className="text-transparent bg-clip-text bg-gradient-to-r from-primary to-[oklch(0.58_0.26_305)]">como una app nativa</span>
        </h2>
        <p className="mx-auto mt-4 max-w-xl text-sm text-muted-foreground">
          Sin ocupar memoria, sin descargas lentas de App Store o Google Play. Un toque y vive en la pantalla de inicio de tu iPhone o Android.
        </p>
      </section>

      {/* Footer */}
      <footer className="border-t border-border py-12 text-center text-xs text-muted-foreground">
        <p>© 2026 Mis Gastos. Diseñado con estilo y total privacidad.</p>
      </footer>
    </div>
  );
}